import fs from 'node:fs';
import assert from 'node:assert/strict';
const dir='data/rule_review_261020/';
const read=f=>JSON.parse(fs.readFileSync(f,'utf8'));
const inputs=read(dir+'excluded_b-input.json');
const evidence=read(dir+'excluded_b-evidence.json');
const norm=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]/g,'');
const unique=a=>[...new Set(a)];
const sourceRows=fs.readFileSync('SOURCES.md','utf8').split(/\r?\n/).filter(l=>/^\| \d+ \|/.test(l));
const exclusions=fs.readFileSync('analysis/analysis_exclusions_261018_0045.md','utf8').split(/\r?\n/);
const allAnalysis=fs.readdirSync('analysis').filter(f=>f.endsWith('.md')).map(f=>({file:'analysis/'+f,text:fs.readFileSync('analysis/'+f,'utf8')}));
const reviewed=new Map();
function packet(id){return evidence.find(x=>x.reviewId===id);}
function base(id){
 const b=inputs.find(x=>x.reviewId===id),p=packet(id);assert(b,id);
 let sources=[...p.sources];
 let priorReviews=unique([...b.analysisFiles,...b.priorRecords.map(x=>x.reviewAnchor||x.currentReview).filter(Boolean).map(x=>x.startsWith('analysis/')?x:'analysis/'+x)]);
 for(const line of exclusions){
  if(!line.startsWith('|'))continue;
  if(line.includes(' | recommended |')||line.includes(' | vetoed |')){
   const title=line.split('|')[1].split(' — ')[0].trim();
   if(norm(title)===norm(b.title)){sources.push(...[...line.matchAll(/\[(\d+)\]\(analysis_/g)].map(m=>+m[1]));priorReviews.push('analysis/analysis_exclusions_261018_0045.md');}
  }else if(/^\| \[\d+\]/.test(line)){
   const titles=line.split('|')[2].split(';').map(norm);
   if(titles.includes(norm(b.title))){sources.push(+line.match(/^\| \[(\d+)\]/)[1]);priorReviews.push('analysis/analysis_exclusions_261018_0045.md');}
  }
 }
 if(!b.priorRecords.length){
  for(const a of allAnalysis.filter(a=>!/exclusions|deductions|pubcap|rescore|quadratic|veto5/.test(a.file))){
   const title=b.title.trim();
   if(!a.text.toLowerCase().includes(title.toLowerCase()))continue;
   // Only a nominated table row or a named hard-exclusion list is provenance, not a passing comparison.
   const nominated=a.text.split(/\r?\n/).some(l=>l.startsWith('|')&&l.toLowerCase().includes('['+title.toLowerCase()+']'));
   if(nominated){for(const sr of sourceRows.filter(l=>l.includes(']('+a.file+')')))sources.push(+sr.split('|')[1]);priorReviews.push(a.file);}
  }
 }
 sources=unique(sources).sort((a,b)=>a-b);
 return {reviewId:id,title:b.title.trim(),author:b.author.trim(),status:'excluded',reason:'',confidence:'high',sources,evidence:unique([...p.evidence,...priorReviews]),priorReviews:unique(priorReviews),changed:false};
}
const codes=['E','S','U','M','D','R','F','A','N','P'];
function rec(num,year,raw,T11,T12,reason,groups,extra={}){
 const id='h'+String(num).padStart(4,'0'),b=inputs.find(x=>x.reviewId===id),p=packet(id),d=base(id);
 const [ea,sumf,dr,np]=groups.split('|');assert(ea&&sumf&&dr&&np,id+' notes');
 const notes=[ea,sumf,sumf,sumf,dr,dr,sumf,ea,np,np].map((t,i)=>codes[i]+': '+t.trim());
 const cache=p.amazon.find(a=>a.selected?.verified&&a.selected.globalCount!==null&&a.selected.evidence?.some(t=>/\bglobal ratings\b/i.test(t)));
 const attempts=p.amazon.flatMap(a=>a.attempts||[]);
 const selected=cache?{...cache.selected,count:cache.selected.globalCount}:null;
 const amazon=selected?{...selected,status:'verified matching Amazon product aggregate; saved snapshot retained',marketplace:new URL(selected.url).hostname,productIdentifier:selected.asin,sourceSnapshot:cache.file,snapshotLimitation:'Saved 2026-10-19 retrieval, not a live count. One product/marketplace only; counts are not combined.',attempts:attempts.map(a=>({url:a.url,retrievedAt:a.retrievedAt,verified:a.verified,count:a.count}))}:{count:null,status:attempts.length?'unknown after saved retrieval attempts; no obscurity deduction':'unknown; targeted Amazon lookup recorded separately; no obscurity deduction',attempts:attempts.map(a=>({url:a.url,retrievedAt:a.retrievedAt,verified:a.verified,count:a.count})),retrievedAt:'2026-10-20',snapshotLimitation:'No matching total-ratings aggregate established; unknown is not zero.'};
 const legacyLink=p.analysisLines.map(x=>x.text.match(/https:\/\/www\.amazon\.(?:de|com)\/dp\/([A-Za-z0-9]+)/)?.[0]).find(Boolean);
 const asin=selected?.asin||b.priorRecords.flatMap(x=>x.appearances||[]).map(x=>x.asin).find(Boolean);
 const purchaseUrl=extra.purchaseUrl||legacyLink||(asin?'https://www.amazon.de/dp/'+asin:'https://www.amazon.de/s?k='+encodeURIComponent(d.title+' '+d.author));
 const reader=selected?`Amazon ${selected.star?.match(/[\d.]+/)?.[0]||'NR'}/5 · ${selected.count.toLocaleString('en-US')} ratings (${new URL(selected.url).hostname}, saved ${selected.retrievedAt.slice(0,10)})`:'NR — no verified comparable reader aggregate';
 const sourceEvidence=cache?[cache.file,selected.url]:p.amazon.map(x=>x.file);
 const originalEvidence=[...d.evidence];
 Object.assign(d,{id:b.id||b.priorRecords[0]?.id||b.sourceIds?.[0]||id,status:'recommended',changed:true,confidence:'moderate',year,yearConfidence:'moderate',yearNote:'Original production year assessed from the retained bibliographic evidence and the work history; later reprints do not reset age.',periodEnd:null,periodConfidence:'high',periodNote:'Explanatory or cross-period argument, not a history bounded by one central period; H13=0.',raw,notes,T11,T12,themeNote:T11===-10?(T12===-10?'The central subject meets both the unwanted-theme and secondary-topic deductions.':'The central subject meets the unwanted-theme deduction; it is not predominantly a rule-12 topic.'):(T12===-10?'Finance, politics, military strategy, power, media or philosophy is the central subject, so T12=-10; T11 does not apply.':'Technology, science, reasoning, production or general organizational mechanisms are central; neither listed negative theme predominates.'),amazon,reader,purchaseUrl,reason:reason+' The former broad skill-development/expert-audience exclusion is not retained. H1 passes; no serious V1–V5 failure is established by the cited evidence.',...extra});
 d.evidence=unique([...originalEvidence,...sourceEvidence,...(extra.evidence||[])]);
 if(d.status==='vetoed')d.reason=reason;
 reviewed.set(id,d);return d;
}
function keep(num,reason,exclusion='H2',confidence='high',extra={}){const id='h'+String(num).padStart(4,'0');reviewed.set(id,{...base(id),exclusion,reason,confidence,...extra});}

// Judgments below are individual rereads of the retained identity, purpose and structure evidence.
